  "Esperando o comando terminar": "正在等待命令结束",
  "Está parado num comando no terminal, esperando ele terminar para continuar o turno.": "正停在终端命令上，等待其完成后继续本轮工作。",
  "Terminou o turno e está esperando {0} shells terminarem. A cada um que termina, o agente recebe o resultado.": "已完成本轮工作，正在等待 {0} 个 shell 结束。每结束一个，智能体就会收到结果。",
  "Terminou o turno e está esperando o shell terminar. Quando ele terminar, o agente recebe o resultado.": "已完成本轮工作，正在等待 shell 结束。结束后，智能体就会收到结果。",
  "Comendo pipoca e assistindo ao terminal": "吃着爆米花看终端",
  "Até 3 min: recosta na cadeira com um balde de pipoca e assiste ao terminal como se fosse um filme.": "3 分钟内：靠在椅子上抱着一桶爆米花，像看电影一样盯着终端。",
  "A pipoca acabou: girando na cadeira": "爆米花吃完了：在椅子上转圈",
  "De 3 a 10 min: a pipoca acaba; braços cruzados, dedos batendo e, de vez em quando, um giro completo na cadeira.": "3 到 10 分钟：爆米花吃完了，抱起双臂、轻敲手指，时不时在椅子上转一整圈。",
  "Já tem teia de aranha na cadeira": "椅子上都结蜘蛛网了",
  "Depois de 10 min: aparece uma teia de aranha na cadeira (ela cresce depois de 20 min) e escapa um bocejo.": "10 分钟后：椅子上出现蜘蛛网（20 分钟后会变大），还忍不住打了个哈欠。",
  "Cochilou esperando o shell": "等 shell 等得打起瞌睡了",
  "Depois de 25 min: cochila na mesa, coberto de teia.": "25 分钟后：趴在桌上打瞌睡，浑身都是蜘蛛网。",
