  "Conectando ao escritório…": "正在连接到办公室…",
  "O servidor do Habblaud não responde. Confira se ele está rodando (npm run dev ou npm start); seguimos tentando.": "Habblaud 服务器无响应。请检查它是否正在运行（npm run dev 或 npm start）；我们会继续重试。",
  "Não foi possível conectar ao servidor do Habblaud. Tentando de novo…": "无法连接到 Habblaud 服务器。正在重试…",
  "Ver demonstração": "查看演示",
  "O escritório está vazio": "办公室空无一人",
  "Não foi possível ligar a demonstração.": "无法开启演示模式。",
  "Tentar agora": "立即重试",
  "Sem conexão com o servidor do Habblaud há algum tempo. O escritório mostra o último estado conhecido.": "已有一段时间未连接到 Habblaud 服务器。办公室当前显示的是最后一次已知状态。",
  "O servidor do Habblaud não responde. Confira se ele está rodando (npm run dev ou npm start).": "Habblaud 服务器无响应。请检查它是否正在运行（npm run dev 或 npm start）。",
