  // scripts/hooks-install.ts
  "Aguardando resposta no Habblaud": "正在等待 Habblaud 中的回复",
  "Uso: npm run hooks:<install|uninstall|status> [-- opções]\n\n  install     acrescenta o hook de permissão do Habblaud em cada conta (faz backup do settings.json)\n  uninstall   tira o hook do Habblaud de cada conta (os outros hooks ficam)\n  status      mostra se o hook está instalado e se o Habblaud está respondendo pedidos\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --node <cmd>     comando do node usado no hook (padrão: detectado no PATH)\n  --port <n>       porta do Habblaud (padrão: HABBLAUD_PORT ou {0})\n  --timeout <s>    quanto o hook espera sua resposta no Habblaud antes de devolver o pedido ao terminal\n                   (padrão: {1} s)\n  -h, --help       mostra esta ajuda\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS).": "用法：npm run hooks:<install|uninstall|status> [-- 选项]\n\n  install     向每个账号添加 Habblaud 权限 hook（会备份 settings.json）\n  uninstall   从每个账号移除 Habblaud hook（保留其他 hooks）\n  status      显示 hook 是否已安装以及 Habblaud 是否正在响应请求\n\n选项：\n  --dry-run        显示将要进行的更改，但不写入任何内容\n  --node <命令>    hook 中使用的 node 命令（默认：从 PATH 自动检测）\n  --port <n>       Habblaud 端口（默认：HABBLAUD_PORT 或 {0}）\n  --timeout <s>    hook 在将请求退回终端前，等待你在 Habblaud 中回复的秒数\n                   （默认：{1} 秒）\n  -h, --help       显示此帮助信息\n\n账号：与服务器一致（包含 projects/ 或 sessions/ 的 ~/.claude*、CLAUDE_CONFIG_DIR 或\nHABBLAUD_CLAUDE_DIRS）。",
  "atualizado (novo caminho do Habblaud, do node ou das opções)": "已更新（新的 Habblaud 路径、node 路径或选项）",
  "instalado": "已安装",
  "hook do Habblaud removido": "已移除 Habblaud hook",
  "--node precisa de um caminho.": "--node 需要一个路径。",
  "Nenhuma conta do Claude Code encontrada (~/.claude* com projects/ ou sessions/). Use HABBLAUD_CLAUDE_DIRS se estiverem em outro lugar.": "未找到任何 Claude Code 账号（包含 projects/ 或 sessions/ 的 ~/.claude*）。如在其他位置，请使用 HABBLAUD_CLAUDE_DIRS。",
  " (esse arquivo não existe mais: o hook falha e vale só o terminal)": "（该文件已不存在：hook 会失败，仅终端生效）",
  "! {0}: o hook aponta para {1}{2}; rode npm run hooks:install para atualizar": "! {0}：hook 指向 {1}{2}；运行 npm run hooks:install 更新",
  "• {0}: instalado ({1}; tempo limite {2} s)": "• {0}：已安装（{1}；超时 {2} 秒）",
  "Habblaud em http://127.0.0.1:{0}: fora do ar (com ele parado, o hook sai na hora e o terminal segue normal).": "http://127.0.0.1:{0} 上的 Habblaud 未运行（停止状态下 hook 会立即退出，终端照常工作）。",
  "Habblaud em http://127.0.0.1:{0}: respondendo pedidos de permissão (com alguma página aberta).": "http://127.0.0.1:{0} 上的 Habblaud：正在响应权限请求（需保持页面打开）。",
  "Habblaud em http://127.0.0.1:{0}: no ar, mas responder pelo escritório está desligado (porta exposta na rede ou HABBLAUD_TERMINAL=0).": "http://127.0.0.1:{0} 上的 Habblaud：运行中，但通过办公室回复已关闭（端口暴露在网络上或 HABBLAUD_TERMINAL=0）。",
  "Pronto. Com o Habblaud aberto no navegador, os pedidos de permissão aparecem no escritório e você": "完成。在浏览器中打开 Habblaud 后，权限请求会显示在办公室中，你",
  "pode aprovar ou recusar por lá; o diálogo continua no terminal e vale o que responder primeiro.": "可以在那里批准或拒绝；终端里仍会显示对话框，以先回复的一方为准。",
  "Sessões abertas costumam recarregar o settings.json sozinhas; se não, reabra a sessão.": "已打开的会话通常会自动重新加载 settings.json；如未生效，请重新打开会话。",
  "Para desfazer: npm run hooks:uninstall": "如需撤销：npm run hooks:uninstall",
  "[hooks] Erro: {0}": "[hooks] 错误：{0}",
  "[hooks] Erro inesperado: {0}": "[hooks] 意外错误：{0}",

  // scripts/mod-install.ts
  "Uso: npm run mod:<install|uninstall|status> [-- opções]\n\n  install     instala o mod do Habblaud no Claude Code de cada conta (marketplace desta pasta + plugins)\n              e tira o que ele substitui: o tap de statusline e o hook de permissão antigos e o mod do\n              nome antigo (codetown)\n  uninstall   tira os plugins e o marketplace do Habblaud de cada conta (e os do nome antigo, se sobraram)\n  status      mostra, por conta, o marketplace, os plugins (e versões) e o que sobrou do jeito antigo\n\nOpções:\n  --sem-permissoes   não instala o plugin de responder permissões pelo escritório (e mantém o hook antigo)\n  --sem-mensagens    não instala o plugin de mandar mensagens pelo escritório (um já instalado continua)\n  --conta <pasta>    só esta conta (ex.: --conta ~/.claude-conta2); pode repetir\n  --dry-run          mostra o que faria, sem instalar nem gravar nada\n  --claude <cmd>     comando do Claude Code (padrão: claude, do PATH)\n  -h, --help         mostra esta ajuda\n\nPrecisa do Claude Code {0} ou mais novo. Em versões anteriores, use o jeito antigo:\nnpm run usage:install (uso ao vivo) e npm run hooks:install (responder permissões); mandar mensagens pelo\nescritório só existe com o mod.\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS). Uso capturado em HABBLAUD_USAGE_DIR (padrão ~/.habblaud/usage).": "用法：npm run mod:<install|uninstall|status> [-- 选项]\n\n  install     在每个账号的 Claude Code 中安装 Habblaud mod（此文件夹的 marketplace + 插件），\n              并移除被替代的旧组件：旧版 statusline tap、旧版权限 hook 以及旧名称\n              （codetown）的 mod\n  uninstall   从每个账号移除 Habblaud 插件和 marketplace（以及残留的旧名称项）\n  status      按账号显示 marketplace、插件（及版本）以及旧方式的残留项\n\n选项：\n  --sem-permissoes   不安装通过办公室回复权限的插件（并保留旧 hook）\n  --sem-mensagens    不安装通过办公室发送消息的插件（已安装的会保留）\n  --conta <文件夹>   仅针对此账号（例如 --conta ~/.claude-conta2）；可重复指定\n  --dry-run          显示将要执行的操作，但不安装也不写入任何内容\n  --claude <命令>    Claude Code 命令（默认：PATH 中的 claude）\n  -h, --help         显示此帮助信息\n\n需要 Claude Code {0} 或更高版本。旧版本请使用旧方式：\nnpm run usage:install（实时用量）和 npm run hooks:install（回复权限）；通过办公室\n发送消息仅支持 mod 方式。\n\n账号：与服务器一致（包含 projects/ 或 sessions/ 的 ~/.claude*、CLAUDE_CONFIG_DIR 或\nHABBLAUD_CLAUDE_DIRS）。用量采集保存于 HABBLAUD_USAGE_DIR（默认 ~/.habblaud/usage）。",
  "o comando \"{0}\" não foi encontrado no PATH": "在 PATH 中找不到命令 \"{0}\"",
  "\"{0} {1}\" não terminou em {2} s": "\"{0} {1}\" 未在 {2} 秒内完成",
