  "hook de permissão antigo removido: o plugin {0} responde no lugar dele": "已移除旧版权限 hook：改由 {0} 插件响应",
  "hook de permissão antigo: {0} (rode npm run hooks:uninstall depois de conferir)": "旧版权限 hook：{0}（确认后请运行 npm run hooks:uninstall）",
  "{0}: não aparece instalado na lista do Claude Code": "{0}：未出现在 Claude Code 的已安装列表中",
