  "{0}: o Claude Code registra a versão {1}, não a {2} (o manifesto em mod/ está com outra versão?)": "{0}：Claude Code 记录的版本是 {1} 而非 {2}（mod/ 中的清单版本不一致？）",
  "rode npm run mod:install para mandar mensagens pelo escritório (plugin {0})": "运行 npm run mod:install 以通过办公室发送消息（插件 {0}）",
  "ainda com o nome antigo ({0}); o docker:up não troca sozinho: rode npm run mod:install": "仍在使用旧名称（{0}）；docker:up 不会自动切换：请运行 npm run mod:install",
