  " (esta pasta: {0}; npm run mod:install ou npm run docker:up atualiza)": "（当前目录：{0}；运行 npm run mod:install 或 npm run docker:up 可更新）",
  "carrega {0} de {1}": "从 {1} 加载 {0}",
  "esta pasta": "当前目录",
  "! nome antigo ainda registrado: {0}; npm run mod:install troca pelo habblaud": "! 旧名称仍在注册中：{0}；运行 npm run mod:install 可替换为 habblaud",
  "! tap de statusline antigo ainda instalado junto com o mod: npm run mod:install tira (ou npm run usage:uninstall)": "! 旧版 statusline tap 仍与 mod 并存：运行 npm run mod:install 移除（或 npm run usage:uninstall）",
  "tap de statusline antigo instalado (jeito antigo; o mod o substitui)": "已安装旧版 statusline tap（旧方式；mod 可替代它）",
  "! hook de permissão antigo ainda no settings.json junto com o plugin: os dois respondem; npm run mod:install tira (ou npm run hooks:uninstall)": "! 旧版权限 hook 仍在 settings.json 中与插件并存：两者会同时响应；运行 npm run mod:install 移除（或 npm run hooks:uninstall）",
  "hook de permissão antigo instalado (jeito antigo; o plugin de permissões o substitui)": "已安装旧版权限 hook（旧方式；权限插件可替代它）",
  "! disableAllHooks está ligado no settings.json desta conta: nenhum mod (nem hook) roda": "! 此账号的 settings.json 中启用了 disableAllHooks：任何 mod（或 hook）都不会运行",
  "--conta precisa da pasta da conta (ex.: --conta ~/.claude-conta2).": "--conta 需要账号文件夹路径（例如 --conta ~/.claude-conta2）。",
  "--claude precisa de um comando ou caminho.": "--claude 需要一个命令或路径。",
