  "não entendi a lista de plugins do Claude Code": "无法解析 Claude Code 的插件列表",
  "--conta {0}: pasta não encontrada.": "--conta {0}：找不到文件夹。",
  "último uso capturado há {0} ({1})": "最近一次用量采集于 {0} 前（{1}）",
  "pelo mod": "通过 mod",
  "pelo tap de statusline": "通过 statusline tap",
  "nenhum uso capturado ainda (chega depois da próxima resposta numa sessão aberta desta conta)": "尚未采集到用量（此账号下已打开会话的下次回复后即会到达）",
  "Nenhuma conta do Claude Code encontrada (~/.claude* com projects/ ou sessions/). Use --conta <pasta> ou HABBLAUD_CLAUDE_DIRS.": "未找到任何 Claude Code 账号（包含 projects/ 或 sessions/ 的 ~/.claude*）。请使用 --conta <文件夹> 或 HABBLAUD_CLAUDE_DIRS。",
  "Não achei {0}: esta pasta não tem o mod (versão antiga do Habblaud? rode git pull).": "找不到 {0}：当前目录没有 mod（Habblaud 版本过旧？请运行 git pull）。",
  "Não consegui rodar o Claude Code: {0}.": "无法运行 Claude Code：{0}。",
  "Instale o Claude Code (https://code.claude.com) ou diga onde ele está: npm run mod:<comando> -- --claude <caminho>": "请安装 Claude Code（https://code.claude.com）或指定其位置：npm run mod:<命令> -- --claude <路径>",
  "! Não entendi a versão do Claude Code (\"{0}\"); sigo assim mesmo.": "! 无法解析 Claude Code 版本（\"{0}\"）；仍继续执行。",
  "O mod precisa do Claude Code {0} ou mais novo, e este é o {1}.": "mod 需要 Claude Code {0} 或更高版本，而当前版本为 {1}。",
  "Atualize o Claude Code (claude update) e rode de novo. Ou use o jeito antigo, que funciona em versões anteriores:": "请更新 Claude Code（claude update）后重试。或改用适用于旧版本的旧方式：",
  "  npm run usage:install    # uso de 5h/semanal ao vivo (tap de statusline)": "  npm run usage:install    # 实时 5 小时/每周用量（statusline tap）",
  "  npm run hooks:install    # responder pedidos de permissão pelo escritório": "  npm run hooks:install    # 通过办公室回复权限请求",
  "Claude Code {0}{1} · Habblaud {2} em {3}": "Claude Code {0}{1} · Habblaud {2} 位于 {3}",
  "(versão desconhecida)": "（版本未知）",
  " — o mod precisa do {0}+": " — mod 需要 {0}+",
  "✓ pasta do uso criada: {0}": "✓ 已创建用量文件夹：{0}",
  "! não consegui criar {0} ({1}); o uso ao vivo não vai ser gravado": "! 无法创建 {0}（{1}）；实时用量将不会被记录",
  "    ✗ settings.json: {0}": "    ✗ settings.json：{0}",
