  "  ✗ settings.json: {0}; o tap e o hook antigos não foram conferidos": "  ✗ settings.json：{0}；未检查旧版 tap 和 hook",
  "  ! disableAllHooks está ligado no settings.json desta conta: o mod não roda até você desligar": "  ! 此账号的 settings.json 中启用了 disableAllHooks：关闭之前 mod 不会运行",
