  "Pronto. Sessões novas do Claude Code já carregam o mod; nas que já estão abertas, rode /reload-plugins (ou": "完成。新的 Claude Code 会话会自动加载 mod；已打开的会话请运行 /reload-plugins（或",
  "reabra a sessão). O uso de 5h/semanal chega ao Habblaud depois da próxima resposta de cada sessão.": "重新打开会话）。5 小时/每周用量会在各会话下次回复后传送到 Habblaud。",
  "Para conferir: npm run mod:status · Para desfazer: npm run mod:uninstall": "检查状态：npm run mod:status · 撤销安装：npm run mod:uninstall",
  "Pronto. Sessões já abertas continuam com o mod até /reload-plugins (ou até reabrir a sessão).": "完成。已打开的会话将继续使用 mod，直到运行 /reload-plugins（或重新打开会话）。",
  "Para voltar ao jeito antigo (Claude Code anterior ao 2.1.287): npm run usage:install e npm run hooks:install": "如需恢复旧方式（Claude Code 2.1.287 之前版本）：npm run usage:install 和 npm run hooks:install",
