  // scripts/statusline-install.ts
  "Uso: npm run usage:<install|uninstall|status> [-- opções]\n\n  install     envolve o statusline de cada conta com o tap do Habblaud (faz backup do settings.json)\n  uninstall   restaura o statusline original de cada conta\n  status      mostra se o tap está instalado e quando chegou o último uso de cada conta\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --node <cmd>     comando do node usado no statusline (padrão: detectado no PATH)\n  -h, --help       mostra esta ajuda\n\nContas: Claude Code (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS) e Antigravity CLI (~/.gemini/antigravity-cli* ou HABBLAUD_ANTIGRAVITY_DIRS).\nUso capturado em HABBLAUD_USAGE_DIR (padrão ~/.habblaud/usage).": "用法：npm run usage:<install|uninstall|status> [-- 选项]\n\n  install     用 Habblaud tap 包装每个账号的 statusline（会备份 settings.json）\n  uninstall   恢复每个账号原有的 statusline\n  status      显示 tap 是否已安装以及各账号最近一次用量到达的时间\n\n选项：\n  --dry-run        显示将要进行的更改，但不写入任何内容\n  --node <命令>    statusline 中使用的 node 命令（默认：从 PATH 自动检测）\n  -h, --help       显示此帮助信息\n\n账号：Claude Code（包含 projects/ 或 sessions/ 的 ~/.claude*、CLAUDE_CONFIG_DIR 或\nHABBLAUD_CLAUDE_DIRS）以及 Antigravity CLI（~/.gemini/antigravity-cli* 或 HABBLAUD_ANTIGRAVITY_DIRS）。\n用量采集保存于 HABBLAUD_USAGE_DIR（默认 ~/.habblaud/usage）。",
  "statusLine em formato desconhecido; nada foi alterado": "statusLine 格式未知，未作任何更改",
  "sem statusline antes: criado um que só captura o uso (não imprime nada)": "此前无 statusline：已创建一个仅采集用量的 statusline（不输出任何内容）",
