  // client/src/ui/world/world-popups.ts
  "Novidade: Habblaud World": "新功能：Habblaud World",
  "Seu escritório agora pode virar um prédio numa cidade online, aceso enquanto os seus agentes trabalham.": "你的办公室现在可以变成在线城市里的一栋大楼，在智能体工作时亮起灯光。",
  "Seu escritório vira um prédio numa cidade em pixel art, aceso enquanto os seus agentes trabalham.": "你的办公室将变成像素风城市里的一栋大楼，在智能体工作时亮起灯光。",
  "Crie um personagem, ande pela cidade e visite os prédios de outras pessoas.": "创建一个角色，漫步城市，拜访他人的大楼。",
  "Cumprimente quem passa e deixe likes nos prédios, sem chat e sem spam.": "向路人打招呼、给大楼点赞，没有聊天也没有垃圾消息。",
  "Nada do seu trabalho sai do computador: só o tema, quantos andares e se cada personagem está ocupado ou à toa.": "你的任何工作内容都不会离开电脑：只会同步主题、楼层数量，以及每个角色是忙碌还是空闲。",
  "Ver a lista": "查看列表",
  "Nada é enviado enquanto você não criar a conta. O acesso é liberado aos poucos, por lista de espera.": "在创建账号之前不会发送任何数据。访问资格正通过候补名单分批开放。",
  "Criar conta": "创建账号",
  "Agora não": "暂不",
  "Não mostrar de novo": "不再显示",
  "Você está na lista de espera": "你已在候补名单中",
  "O acesso é liberado aos poucos, em lotes. Avisamos por e-mail quando chegar a sua vez.": "访问资格正分批逐步开放。轮到你时，我们会通过邮件通知你。",
  "Enquanto isso, o Habblaud continua normal e nada do escritório é enviado.": "在此期间，Habblaud 一切照常运行，办公室的任何数据都不会被发送。",
  "Entendi": "知道了",
  "Chegou a sua vez: crie o seu personagem e entre na cidade.": "轮到你了：创建你的角色，进入城市吧。",

