  "Dispositivo revogado.": "设备已撤销。",
  "Fechado a visitas": "谢绝访客",
  "Dá para ver o prédio por fora, mas ninguém entra.": "其他人可以从外部看到大楼，但无法进入。",
  "Esconder o país": "隐藏国家/地区",
  "No lugar da bandeira do país (visto pelo IP da conexão) aparece uma bandeira neutra.": "将显示中性旗帜，而非根据连接 IP 识别的国家/地区旗帜。",
  "Mostrar o consumo de tokens": "显示 token 用量",
  "Total do dia e da semana do prédio inteiro, só em faixas (até 100 mil, 1 milhão…). Nunca o custo.": "整栋大楼的当日与本周总用量，仅按区间显示（如 10 万以内、100 万……），绝不显示费用。",
  "Entrar no placar": "加入排行榜",
  "O prédio pode aparecer nos placares de tokens da cidade.": "大楼可出现在城市的 token 排行榜中。",
  "Mostrar as compactações": "显示上下文压缩",
  "Quando um agente compacta o contexto, a lixeira da sala enche. Sai só o fato, nada do conteúdo.": "当智能体压缩上下文时，房间里的垃圾桶会变满。仅发送这一事件，绝不发送任何内容。",
  "Habblaud World": "Habblaud World",
  "Só pelo computador": "仅限本机操作",
  "Sem conta": "无账号",
  "Na lista de espera": "候补名单中",
  "Liberado": "已获批",
  "A conta do Habblaud World só pode ser mexida no próprio computador, com o Habblaud em acesso local (bind 127.0.0.1) e aberto por http://localhost.": "Habblaud World 账号仅可在本机管理，且需在 Habblaud 仅限本地访问（绑定 127.0.0.1）并通过 http://localhost 打开时操作。",
  "Já tenho conta": "已有账号",
  "Leve o seu escritório para uma cidade em pixel art: um prédio seu, aceso enquanto os agentes trabalham, e um personagem para passear e visitar os prédios de outras pessoas.": "把你的办公室搬进像素风城市：拥有一栋属于自己的大楼，智能体工作时灯火通明；还能操控角色在城里漫步，拜访其他人的大楼。",
  "O acesso é liberado aos poucos: quem cria a conta entra numa lista de espera.": "访问权限将分批开放：新建账号会先进入候补名单。",
  "O que sai do seu computador": "会从你电脑发送的数据",
  "Quem visita o mundo vê, ao vivo, quantos projetos e agentes você está rodando e o que cada personagem está fazendo (trabalhando, esperando, à toa). Ninguém vê quais projetos são, o que os agentes fazem, nem quem você é: só o nickname e o avatar que você escolheu.": "访问世界的人可以实时看到你正在运行多少个项目和智能体，以及每个角色正在做什么（工作中、等待中、空闲）。没人能看到具体是什么项目、智能体在做什么，也不知道你是谁——只能看到你选的昵称和形象。",
  "Sai:": "会发送：",
  "o tema do escritório; um andar por sala aberta, com um código aleatório que muda todo dia; de cada agente, se é principal ou subagente, a ferramenta, o status, a aparência, um nome sorteado e a faixa de tarefas concluídas no dia; os tokens do prédio arredondados em faixas (dá para desligar); se você ligar, o fato de um agente ter compactado o contexto; a versão e o commit do Habblaud, com a marca de cópia modificada; e o idioma da interface, só para os e-mails.": "办公室主题；每个打开的房间对应一个楼层，附带每天更换的随机编号；每个智能体是主智能体还是子智能体、所用工具、状态、外观、随机抽选的名字以及当日完成任务数的区间；大楼的 token 用量区间（可关闭）；若你开启，还会发送智能体压缩上下文的事件；Habblaud 版本号和构建 commit（以及是否经过修改的标记）；界面语言（仅用于发送邮件）。",
  "Nunca sai:": "绝不发送：",
  "caminhos e nomes de projetos, títulos de sessão, comandos, mensagens, código, custo, a sua conta do Claude, o seu e-mail e o nome do computador.": "项目路径与名称、会话标题、命令、消息、代码、费用、你的 Claude 账号、你的邮箱以及电脑名称。",
  "Com os dados que saem não dá para saber quem você é nem em que trabalha.": "仅凭发送出去的数据，无法推断出你的身份或你在做什么项目。",
  "Os agentes trabalham sem você: prédio aceso não quer dizer que você está no computador. Se preferir, use o modo discreto ou feche o prédio a visitas.": "智能体会自行工作：大楼亮灯并不代表你就在电脑前。如有需要，请开启隐私模式或将大楼设为谢绝访客。",
  "Ver a lista completa": "查看完整列表",
  "Pelo menos 12 caracteres. Uma frase longa vale mais do que símbolos; senhas que já vazaram são recusadas.": "至少 12 个字符。长短语比复杂符号更安全；曾发生泄露的密码会被拒绝。",
