  "De 3 a 20 caracteres: letras de um só alfabeto, números, espaço, _ - e . É o seu nome no mundo e não pode repetir o de ninguém.": "3 至 20 个字符：仅限同一文字系统的字母、数字、空格、_、- 和 .。这是你在世界中的名字，不可与他人重复。",
  "Dá para trocar uma vez a cada 30 dias.": "每 30 天可修改一次。",
  "3 a 20 caracteres; é o nome do seu personagem e fica reservado para você, mesmo na lista de espera. Único no mundo.": "3 至 20 个字符；这是你的角色名称，即使在候补名单中也会为你保留。全服唯一。",
