  "Escolha um nome novo: a moderação trocou o seu nome de jogador. O nome novo entra na hora, sem esperar os 30 dias.": "请选择一个新名称：管理员已更改你的玩家名。新名称将立即生效，无需等待 30 天。",
  "Escolha 2 ou 3 traços. Os que não combinam com os já escolhidos ficam apagados.": "请选择 2 或 3 个特征。与已选特征不搭的选项会变灰。",
  "Aparece no seu perfil, traduzida para quem lê. No mundo não há texto livre além do nome.": "会显示在你的个人资料中，并自动翻译给查看者。除名称外，世界中不支持自由输入文本。",
