  // client/src/ui/world/world-model.ts
  "A senha precisa ter pelo menos 12 caracteres.": "密码至少需要 12 个字符。",
  "A senha pode ter no máximo 128 caracteres.": "密码最多不能超过 128 个字符。",
  "A senha não pode ser o seu e-mail.": "密码不能与邮箱相同。",
  "A senha não pode ser só uma repetição (como \"aaaaaaaaaaaa\").": "密码不能仅为重复字符（例如 \"aaaaaaaaaaaa\"）。",
  "O nome precisa ter de 3 a 20 caracteres.": "名称长度需为 3 至 20 个字符。",
  "Use só letras, números, espaço, _ - e . no nome.": "名称中仅可使用字母、数字、空格、_、- 和 .。",
  "Use letras de um só alfabeto no nome.": "名称中的字母须来自同一文字系统。",
  "Tire do nome os caracteres invisíveis e os espaços especiais.": "请移除名称中的不可见字符和特殊空格。",
  "O nome precisa ter pelo menos uma letra.": "名称中必须至少包含一个字母。",
  "Este nome é reservado. Escolha outro.": "该名称为保留字，请换一个。",
  "Código errado ou vencido. Confira o e-mail ou peça outro código.": "验证码错误或已过期。请检查邮件或重新获取。",
  "E-mail ou senha não conferem.": "邮箱或密码不匹配。",
  "Falta confirmar o e-mail: mandamos um código novo.": "尚未验证邮箱：我们已发送新的验证码。",
  "Esta conta foi banida do Habblaud World. Para recorrer, responda ao e-mail do banimento.": "此账号已被 Habblaud World 封禁。如需申诉，请回复封禁通知邮件。",
  "Este nome já está em uso no mundo. Escolha outro.": "该名称在世界中已被使用，请换一个。",
  "Nome inválido: de 3 a 20 caracteres, com letras de um só alfabeto, números, espaço, _ - e .": "名称无效：需为 3 至 20 个字符，仅限同一文字系统的字母、数字、空格、_、- 和 .。",
  "Este nome não é permitido. Escolha outro.": "该名称不被允许，请换一个。",
  "O Habblaud World não está ligado neste Habblaud (HABBLAUD_WORLD_URL recusada; veja o log do servidor).": "此 Habblaud 未启用 Habblaud World（HABBLAUD_WORLD_URL 被拒绝；请查看服务端日志）。",
  "Muitas tentativas seguidas. Espere alguns minutos e tente de novo.": "连续尝试次数过多，请等待几分钟后重试。",
  "O servidor do Habblaud World não respondeu. Tente de novo em instantes.": "Habblaud World 服务器未响应，请稍后重试。",
  "A conta do World só pode ser mexida pelo próprio computador, com o Habblaud aberto em localhost.": "World 账号仅可在本机管理，且需通过 localhost 打开 Habblaud。",
  "Esta conta está suspensa no Habblaud World por enquanto.": "此账号目前在 Habblaud World 中处于暂停状态。",
  "A sessão do Habblaud World neste computador terminou. Entre de novo.": "此电脑上的 Habblaud World 会话已过期，请重新登录。",
  "O nome só pode ser trocado uma vez a cada 30 dias.": "名称每 30 天只能修改一次。",
  "A senha precisa ter de 12 a 128 caracteres.": "密码长度需为 12 至 128 个字符。",
  "Senha fraca: não use o e-mail, o nome de jogador nem só repetição.": "密码强度过弱：请勿使用邮箱、玩家名或纯重复字符。",
  "Esta senha aparece em vazamentos de dados conhecidos. Escolha outra.": "此密码曾出现在已知的数据泄露中，请更换其他密码。",
  "E-mail inválido. Confira o endereço.": "邮箱格式无效，请检查地址。",
  "A verificação anti-robô não passou. Tente de novo em instantes.": "人机验证未通过，请稍后重试。",
  "Esta conta já tem 3 computadores; revogue um em Dispositivos.": "此账号已绑定 3 台电脑；请先在“设备”中撤销一台。",
  "Crie o personagem primeiro.": "请先创建角色。",
  "O Habblaud World está em manutenção. Tente de novo mais tarde.": "Habblaud World 正在维护中，请稍后重试。",
  "O servidor do mundo teve um erro; tente de novo.": "世界服务器发生错误，请重试。",
  "Este dispositivo não está mais na conta.": "此设备已不在该账号下。",
  "O servidor do Habblaud World não encontrou o que foi pedido.": "Habblaud World 服务器未找到请求的内容。",
  "O pedido saiu num formato que o servidor não aceita. Atualize o Habblaud e tente de novo.": "请求格式不被服务器接受。请更新 Habblaud 后重试。",
  "O servidor do Habblaud World respondeu algo inesperado. Tente de novo em instantes.": "Habblaud World 服务器返回了异常响应，请稍后重试。",
  "Não deu para gravar a sessão neste computador: ela vale só até o Habblaud reiniciar.": "无法在此电脑上保存会话：当前会话仅在 Habblaud 重启前有效。",
  "A conta do World só pode ser mexida com o Habblaud acessível apenas pelo próprio computador (acesso local, bind 127.0.0.1).": "仅当 Habblaud 仅限本机访问（本地访问，绑定 127.0.0.1）时，才能管理 World 账号。",
  "O servidor recusou o e-mail ou a senha. A senha precisa ter de 12 a 128 caracteres e não pode estar numa lista de senhas vazadas.": "服务器拒绝了邮箱或密码。密码需为 12 至 128 个字符，且不能位于已泄露密码列表中。",
  "O servidor recusou o personagem. Confira o nome, os traços (2 ou 3) e a frase de apresentação.": "服务器拒绝了角色信息。请检查名称、性格特征（2 或 3 个）以及介绍语。",
  "O servidor recusou as opções de visibilidade.": "服务器拒绝了可见性设置。",
  "O servidor recusou o pedido. Confira os dados e tente de novo.": "服务器拒绝了请求，请检查填写内容后重试。",
  "Algo deu errado. Tente de novo em instantes.": "出错了，请稍后重试。",
