  "Seu prédio": "你的大楼",
  "Seu prédio agora": "你的大楼当前状态",
  "Sem personagem": "尚未创建角色",
  "Pausado": "已暂停",
  "Retomar": "恢复",
  "1 andar": "1 个楼层",
  "{0} andares": "{0} 个楼层",
