  "Última remessa: {0}": "上次上传：{0}",
  "Nenhuma remessa ainda": "尚未上传",
  "Aceso no mundo: um andar por sala aberta e cada personagem no status de agora. Os tokens, se você deixar, aparecem só em faixas, no medidor da fachada.": "已在世界中亮灯：每个打开的房间对应一个楼层，每个角色显示当前状态。若你允许显示 token，仅会以区间形式展示在外墙仪表上。",
  "O prédio acende com a primeira remessa.": "首次上传后大楼即会亮灯。",
  "Sem conexão com o mundo agora: o Habblaud tenta de novo sozinho. Com 2 minutos sem notícias, o prédio apaga.": "当前与世界断开连接：Habblaud 会自动重试。若 2 分钟仍无响应，大楼将会熄灯。",
  "Pausado: seu prédio está apagado, mas você pode andar pela cidade. Nada do escritório sai deste computador.": "已暂停：你的大楼已熄灯，但你仍可在城市中漫步。办公室的任何数据都不会离开此电脑。",
  "Crie o seu personagem: o prédio entra no mundo junto com ele.": "创建你的角色：大楼会随角色一同进入世界。",
  "Pausar interrompe o envio na hora e apaga o prédio no mundo.": "暂停会立即停止发送数据，并让世界中的大楼熄灯。",
  "Retomar volta a enviar e acende o prédio.": "恢复后会重新发送数据并点亮大楼。",
  "Pausado por 30 dias, o prédio some do mapa e, 30 dias depois, é retirado; retomar antes disso traz de volta, no mesmo lote.": "暂停满 30 天后大楼会从地图上隐藏，再过 30 天将被移除；在此之前恢复即可在原地重新出现。",
  "O mundo recusou a última remessa.": "世界拒绝了上次上传。",
  "O pacote saiu fora do formato do protocolo. Atualize o Habblaud.": "数据包不符合协议格式，请更新 Habblaud。",
  "O escritório passou dos limites do mundo (64 andares, 64 agentes por andar, 256 agentes ou 64 KB).": "办公室超出了世界上限（64 个楼层、每层 64 个智能体、总计 256 个智能体或 64 KB）。",
  "Um nome de personagem não está na lista de nomes do mundo.": "有角色名称不在世界的名称列表中。",
  "Uma peça de aparência está fora das paletas do editor.": "有外观部件不在编辑器的调色板范围内。",
  "Um código de andar ou de agente está fora do formato.": "有楼层编号或智能体编号格式不正确。",
  "Remessas demais em pouco tempo (o limite é 12 por minuto). A próxima vai normalmente.": "短时间内上传过于频繁（上限为每分钟 12 次），下一次将正常发送。",
  "Um motivo que esta versão do Habblaud não conhece.": "当前版本的 Habblaud 无法识别该原因。",
  "Ver o que foi enviado": "查看已发送内容",
  "O que foi enviado": "已发送的内容",
  "Nada saiu deste computador ainda: o prédio entra no mundo com a primeira remessa.": "尚未从此电脑发送任何数据：首次上传后大楼即会进入世界。",
