  "Recusada pelo mundo.": "已被世界拒绝。",
  "Isto é tudo o que saiu do seu computador. Nenhum caminho, nome de projeto, texto ou horário do escritório.": "这就是从你电脑发出的全部内容，不包含任何路径、项目名、文本或办公室时间。",
  "Pacote enviado (JSON)": "已发送数据包（JSON）",
  "O tema também vale para o seu prédio no Habblaud World.": "该主题也会应用到你在 Habblaud World 中的大楼。",
  "Não deu para mandar o tema para o prédio: {0}": "无法将主题同步至大楼：{0}",
  "no mundo": "在世界中",
  "pausado": "已暂停",
  "Seu prédio está aceso no Habblaud World: {0} e {1}. Clique para abrir o Habblaud World.": "你的大楼已在 Habblaud World 亮灯：{0}、{1}。点击打开 Habblaud World。",
  "Pausado: seu prédio está apagado, mas você pode andar pela cidade. Nada do escritório sai deste computador; clique para retomar.": "已暂停：你的大楼已熄灯，但你仍可在城市中漫步。办公室数据不会离开此电脑；点击即可恢复。",
  "Sem conexão com o Habblaud World agora; o Habblaud tenta de novo sozinho. Clique para ver o seu prédio.": "当前与 Habblaud World 断开连接；Habblaud 会自动重试。点击查看你的大楼。",
  "Um erro no servidor do mundo. A próxima remessa tenta de novo.": "世界服务器出错，下次上传将自动重试。",
  "Habblaud World: o servidor do mundo não confirmou a saída do prédio ({0}).": "Habblaud World：世界服务器未确认大楼离开世界（{0}）。",
  "A conta voltou para a lista de espera: o prédio sai do mundo até o acesso ser liberado de novo.": "账号已退回候补名单：大楼将暂时离开世界，直至访问权限再次开放。",
  "A sua conta conectou o prédio em outro computador, e este parou de enviar.": "你的账号已在另一台电脑上连接大楼，本机已停止发送。",
  "Atualize o Habblaud": "更新 Habblaud",
  "Conectado em outro computador": "已在另一台电脑连接",
  "Confirmar: sair do mundo": "确认：离开世界",
  "Conta banida": "账号已封禁",
  "Conta suspensa": "账号已暂停",
  "Entre de novo": "重新登录",
  "Esta conta está suspensa no Habblaud World: o prédio fica apagado e nada sai deste computador.": "此账号在 Habblaud World 中已被暂停：大楼保持熄灯状态，且不会从此电脑发送任何数据。",
  "Esta versão do Habblaud não entra mais no mundo. Atualize para o prédio voltar a acender.": "当前版本的 Habblaud 已无法接入世界。请更新以重新点亮大楼。",
  "Fora do mundo": "已离开世界",
  "O Habblaud World baniu esta conta: o prédio saiu do mundo e nada mais sai deste computador.": "Habblaud World 已封禁此账号：大楼已离开世界，且不再从此电脑发送任何数据。",
  "O mundo contou {0}.": "世界统计为 {0}。",
  "O mundo não encontrou o seu personagem: crie de novo para o prédio voltar.": "世界未找到你的角色：请重新创建角色以让大楼恢复上线。",
  "O mundo recebeu os mesmos {0}.": "世界收到的也是 {0}。",
  "O prédio volta a subir daqui, e o outro computador para de enviar.": "大楼将改为从本机上传，另一台电脑会停止发送。",
  "O servidor do mundo não reconheceu este computador: entre de novo na conta.": "世界服务器无法识别此电脑：请重新登录账号。",
  "parado": "已停止",
  "Pausar apaga o prédio e guarda o lote: retomar traz de volta, no mesmo lugar. Sair do mundo retira o prédio na hora e libera o lote; a conta e o personagem continuam, e voltar depois cria um prédio novo, em outro lote.": "暂停会让大楼熄灯并保留地块：恢复后仍在原地出现。离开世界会立即移除大楼并释放地块；账号和角色仍会保留，之后返回会在新地块新建一栋大楼。",
  "Sair do mundo": "离开世界",
  "Se a suspensão já acabou, o prédio volta a acender.": "若暂停期限已结束，大楼将重新亮灯。",
  "Seu prédio parou de subir ao Habblaud World. Clique para ver o motivo.": "你的大楼已停止向 Habblaud World 上传数据。点击查看原因。",
  "Trazer para este computador": "切换到此电脑",
  "Você saiu do mundo: o prédio foi retirado e o lote, liberado. Dá para andar pela cidade; nada do escritório sai deste computador.": "你已离开世界：大楼已被移除，地块已释放。你仍可在城市中漫步；办公室数据不会离开此电脑。",
  "Voltar ao mundo": "返回世界",
  "Voltar cria um prédio novo, em outro lote; a conta e o personagem são os mesmos.": "返回会在新地块新建一栋大楼；账号与角色保持不变。",

