  "Prédio apagado: o dono pausou ou não está com o Habblaud aberto. As salas ficam escuras e vazias.": "大楼已熄灯：主人暂停了同步或未打开 Habblaud。房间处于漆黑且空置状态。",
  "Modo discreto: o dono não mostra os agentes. As salas aparecem vazias, com a luz acesa.": "隐私模式：主人隐藏了智能体。房间亮着灯，但看起来空无一人。",
  "O mundo está em manutenção; tentamos de novo em instantes.": "世界正在维护中，稍后将重试。",
  "Conta excluída": "账号已删除",
  "A conta do Habblaud World foi excluída: o prédio e o perfil saíram do mundo e nada mais sai deste computador.": "Habblaud World 账号已删除：大楼和个人资料已从世界中移除，此电脑不再向外发送任何数据。",
  "Habblaud World: desligado (HABBLAUD_WORLD={0}).": "Habblaud World：已关闭（HABBLAUD_WORLD={0}）。",
  "Habblaud World: ligado: {0}": "Habblaud World：已开启：{0}",
  "Habblaud World: ligado: {0} (padrão)": "Habblaud World：已开启：{0}（默认）",
  "HABBLAUD_WORLD_URL recusada": "HABBLAUD_WORLD_URL 被拒绝",
  "Habblaud World: desligado ({0}).": "Habblaud World：已关闭（{0}）。",
  "A conta do Habblaud World foi excluída. O prédio e o perfil saíram do mundo na hora; o resto é apagado do banco em 7 dias e dos backups em até 30.": "Habblaud World 账号已删除。大楼和个人资料已立即从世界中移除；其余数据将在 7 天内从数据库中清除，并在 30 天内从备份中清除。",
  "Habblaud World: conta excluída; a sessão e o world.json foram apagados deste computador.": "Habblaud World：账号已删除；会话和 world.json 已从此电脑中移除。",
  "os dados da conta só saem pela própria página do Habblaud": "账号数据只能通过 Habblaud 自身页面导出",
  "a conta, o personagem, os likes dados e recebidos, os bloqueios, as denúncias feitas e os dispositivos são apagados do banco.": "账号、角色、送出和收到的赞、拉黑记录、提交的举报以及设备信息都将从数据库中清除。",
  "Abre um e-mail para {0}: conte o que aconteceu, e uma pessoa revê o caso.": "打开致 {0} 的邮件：说明事情经过，将由人工复核。",
  "Abre um e-mail para {0}: se for engano, uma pessoa revê os números e tira o selo.": "打开致 {0} 的邮件：如属误判，将由人工复核数据并移除该标记。",
  "Avisar por e-mail antes de retirar meu prédio por inatividade": "因长期不活跃移除我的大楼前通过邮件通知我",
