  "Mandamos um código de 6 dígitos para {0}. Digite o código para excluir a conta.": "我们已向 {0} 发送了 6 位验证码。输入验证码即可删除账号。",
  "Mandar o código": "发送验证码",
  "Na hora:": "立即生效：",
  "Não verificado": "未验证",
  "O aviso de inatividade fica disponível depois de criar o personagem.": "创建角色后即可开启不活跃提醒。",
  "O mundo marcou o seu prédio como \"não verificado\": os números pareceram fora do normal e estão em revisão. Ele continua no mundo, mas fora de placares e destaques.": "世界已将你的大楼标记为“未验证”：数据存在异常，正在审核中。大楼仍保留在世界中，但不会出现在排行榜和推荐展示中。",
  "o prédio e o perfil somem do mundo, e este computador sai da conta.": "大楼和个人资料会从世界中消失，此电脑也将退出账号登录。",
  "Os números deste prédio pareceram fora do normal e estão em revisão; enquanto isso, ele fica fora de placares e destaques.": "该大楼的数据存在异常，正在审核中；在此期间，它不会出现在排行榜和推荐展示中。",
  "Para confirmar, mandamos um código de 6 dígitos para o e-mail da conta ({0}).": "为进行确认，我们将向账号邮箱（{0}）发送一个 6 位验证码。",
  "Pronto: o arquivo {0} foi para a pasta de downloads.": "完成：文件 {0} 已保存到下载文件夹。",
  "Recorrer por e-mail": "通过邮件申诉",
  "Se quiser guardar uma cópia, baixe os seus dados antes.": "如果想保留副本，请先下载你的数据。",
  "Sem notícias deste Habblaud por 7 dias, o prédio some do mapa e, 30 dias depois, é retirado. O e-mail chega 3 dias antes da retirada.": "若此 Habblaud 连续 7 天未上报状态，大楼将从地图上隐藏，30 天后将被移除。提醒邮件会在移除前 3 天送达。",
  "Seus dados": "你的数据",
  "somem também dos backups.": "同时从备份中彻底清除。",
  "Tem certeza? O prédio e o perfil saem do mundo assim que você digitar o código.": "确定要删除吗？一旦输入验证码，大楼和个人资料将立即从世界中移除。",
  "Um arquivo JSON com o que o Habblaud World guarda da sua conta: e-mail, datas, personagem, visibilidade, dispositivos, prédio, likes dados, bloqueios e denúncias feitas. Dá para baixar uma vez por dia.": "包含 Habblaud World 所保存账号信息的 JSON 文件：邮箱、时间记录、角色、可见性设置、设备、大楼、送出的赞、拉黑记录和提交的举报。每天可下载一次。",
  "O pacote contradiz o anterior de um jeito que o Habblaud não produz: o mundo o descartou, e o prédio fica com o último aceito. As próximas remessas vão normalmente.": "该数据包与上一条记录存在 Habblaud 正常不会产生的矛盾：世界已将其丢弃，大楼保持上一次被接受的状态。后续上报将正常进行。",

